"""Min Stack — pair every value with the minimum below it.

Storing (value, running_min) makes getMin O(1) without a second structure.

Time: O(1) per operation   Space: O(n)
"""


class MinStack:
    def __init__(self):
        self._stack = []          # (value, min so far)

    def push(self, val: int) -> None:
        current_min = val if not self._stack else min(val, self._stack[-1][1])
        self._stack.append((val, current_min))

    def pop(self) -> None:
        self._stack.pop()

    def top(self) -> int:
        return self._stack[-1][0]

    def getMin(self) -> int:
        return self._stack[-1][1]
